package meter

import "testing"

func TestReady(t *testing.T) {
	if !Ready() {
		t.Fatal("baseline not ready")
	}
}

// Package meter 是订阅、用量与账单的本地基线。
package meter

// Ready 表示基线可以运行。
func Ready() bool { return true }

