		t.Fatalf("pay2: %+v %v", r2, err)
	}
	if _, err := s.RecordPayment("a", "p3", jan(2026), 1); !errors.Is(err, ErrPaymentExceedsBalance) {
		t.Fatalf("pay settled bill: %v", err)
	}
}

